#include "box3d/box3d.h"
#include <cassert>
#include <cstdio>
#include <cstring>

static bool overlap(b3ShapeId,void*){return true;}
static float cast(b3ShapeId,b3Pos,b3Vec3,float,uint64_t,int,int,void*){return 1.0f;}
static bool plane(b3ShapeId,const b3PlaneResult*,int,void*){return true;}
static b3QueryFilter filter(int kind){static const char* names[]={"pr10-aabb","pr10-overlap","pr10-ray","pr10-shape","pr10-closest","pr10-mover","pr10-planes"};auto f=b3DefaultQueryFilter();f.id=100+kind;f.name=names[kind];return f;}
static b3BodyId body(b3WorldId world,const char* name,b3Pos p,bool dynamic){auto d=b3DefaultBodyDef();d.name=name;d.position=p;if(dynamic)d.type=b3_dynamicBody;return b3CreateBody(world,&d);}
static b3ShapeId box(b3BodyId id,const char* name,float hx,float hy,float hz){auto d=b3DefaultShapeDef();auto h=b3MakeBoxHull(hx,hy,hz);auto s=b3CreateHullShape(id,&d,&h.base);b3Shape_SetName(s,name);return s;}
static void queries(b3WorldId world,bool hit){const b3Pos origin=hit?b3Pos{0,2,0}:b3Pos{30,2,30};const float x=hit?0:30,z=hit?0:30;const b3AABB a={{x-.5f,-1,z-.5f},{x+.5f,.75f,z+.5f}};b3World_OverlapAABB(world,a,filter(0),overlap,nullptr);b3ShapeProxy proxy={};proxy.count=1;proxy.points[0]=b3Vec3_zero;proxy.radius=.25f;b3World_OverlapShape(world,{x,.25f,z},&proxy,filter(1),overlap,nullptr);b3World_CastRay(world,origin,{0,-4,0},filter(2),cast,nullptr);b3World_CastShape(world,origin,&proxy,{0,-4,0},filter(3),cast,nullptr);b3World_CastRayClosest(world,origin,{0,-4,0},filter(4));b3World_CastRayClosest(world,origin,{0,-4,0},filter(4));const b3Capsule mover={{0,-.2f,0},{0,.2f,0},.2f};b3World_CastMover(world,origin,&mover,{0,-4,0},filter(5),nullptr,nullptr);b3World_CollideMover(world,{x,.1f,z},&mover,filter(6),plane,nullptr);b3World_CastRayClosest(world,origin,{0,-4,0},b3DefaultQueryFilter());}
int main(int argc,char** argv){assert(argc==2);auto wd=b3DefaultWorldDef();wd.workerCount=1;auto world=b3CreateWorld(&wd);auto ground=body(world,"fixture floor",{0,-.5f,0},false);box(ground,"floor hull",8,.5f,8);auto resting=body(world,"resting box",{0,.5f,0},true);box(resting,"contact box",.5f,.5f,.5f);auto sphereBody=body(world,"offset spheres",{-2,1,0},true);auto sd=b3DefaultShapeDef();b3Sphere sphere={{0,0,0},.3f};auto sphereShape=b3CreateSphereShape(sphereBody,&sd,&sphere);b3Shape_SetName(sphereShape,"first sphere");sphere.center={0,.7f,0};b3Shape_SetName(b3CreateSphereShape(sphereBody,&sd,&sphere),"offset sphere");auto capsuleBody=body(world,"capsule",{2,1.2f,0},true);b3Capsule cap={{0,-.3f,0},{0,.3f,0},.2f};b3Shape_SetName(b3CreateCapsuleShape(capsuleBody,&sd,&cap),"Y capsule");auto arm=body(world,"hinged arm",{0,3,0},true);box(arm,"arm hull",1,.1f,.1f);auto jd=b3DefaultRevoluteJointDef();jd.base.bodyIdA=ground;jd.base.bodyIdB=arm;jd.base.localFrameA.p={0,3.5f,0};jd.base.localFrameB.p=b3Vec3_zero;b3CreateRevoluteJoint(world,&jd);auto recording=b3CreateRecording(65536);b3World_StartRecording(world,recording);b3BodyId spawned=b3_nullBodyId;
for(int frame=0;frame<64;++frame){if(frame==8){spawned=body(world,"spawned then deleted",{3,2,1},true);box(spawned,"temporary hull",.25f,.25f,.25f);}if(frame==16){b3DestroyBody(spawned);spawned=b3_nullBodyId;}queries(world,frame%2==0);b3World_Step(world,1.0f/60,4);}
b3World_StopRecording(world);assert(b3SaveRecordingToFile(recording,argv[1]));const int bytes=b3Recording_GetSize(recording);assert(bytes>0&&bytes<4*1024*1024);b3DestroyWorld(world);assert(b3ValidateReplay(b3Recording_GetData(recording),bytes,1));auto player=b3CreatePlayer(b3Recording_GetData(recording),bytes,1);assert(player);auto info=b3RecPlayer_GetInfo(player);assert(info.frameCount==64);unsigned kindCount[7]={},hitCount[7]={},missCount[7]={},duplicateKeyFrames=0,untagged=0;int minBodies=100,maxBodies=0,spawnVisibleFrames=0,removedOrdinalFrames=0;unsigned contacts=0;
while(b3RecPlayer_StepFrame(player)){auto replayWorld=b3RecPlayer_GetWorldId(player);auto counters=b3World_GetCounters(replayWorld);if(counters.bodyCount<minBodies)minBodies=counters.bodyCount;if(counters.bodyCount>maxBodies)maxBodies=counters.bodyCount;if(counters.bodyCount==6)++spawnVisibleFrames;if(b3RecPlayer_GetBodyCount(player)==6&&B3_IS_NULL(b3RecPlayer_GetBodyId(player,5)))++removedOrdinalFrames;uint64_t closestKey=0;int repeats=0;for(int q=0;q<b3RecPlayer_GetFrameQueryCount(player);++q){auto query=b3RecPlayer_GetFrameQuery(player,q);assert(query.type>=0&&query.type<7);++kindCount[query.type];if(query.hitCount)++hitCount[query.type];else ++missCount[query.type];if(query.key==0)++untagged;if(query.id==104){if(!closestKey)closestKey=query.key;else if(query.key==closestKey)++repeats;}}if(repeats)++duplicateKeyFrames;auto rest=b3RecPlayer_GetBodyId(player,1);contacts+=b3Body_GetContactCapacity(rest);}
assert(!b3RecPlayer_HasDiverged(player));assert(minBodies==5&&maxBodies==6&&spawnVisibleFrames==8&&removedOrdinalFrames==48);assert(duplicateKeyFrames==64&&untagged==64&&contacts>0);for(int i=0;i<7;++i)assert(kindCount[i]>=64&&hitCount[i]>0&&missCount[i]>0);std::printf("{\"status\":\"REAL_BOX3D_RECORDING_VALIDATED\",\"frames\":64,\"bytes\":%d,\"min_bodies\":%d,\"max_bodies\":%d,\"spawn_visible_frames\":%d,\"removed_ordinal_frames\":%d,\"same_key_instance_frames\":%u,\"untagged_queries\":%u,\"contact_capacity_sum\":%u,\"query_kinds\":[",bytes,minBodies,maxBodies,spawnVisibleFrames,removedOrdinalFrames,duplicateKeyFrames,untagged,contacts);for(int i=0;i<7;++i){if(i)std::putchar(',');std::printf("{\"kind\":%d,\"queries\":%u,\"positive\":%u,\"miss\":%u}",i,kindCount[i],hitCount[i],missCount[i]);}std::puts("]}");b3DestroyPlayer(player);b3DestroyRecording(recording);assert(b3GetWorldCount()==0);}
